window.RP_SESSION={"id":"S-3e59483b1d5a","messages":[{"id":"RP-0222993","time":"2026-08-10T23:42:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"한밤중, 길드 앞 거리.\n오즈발드는 골기아의 지도를 그리기 위해, 오늘도 발걸음을 나섭니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0222994","time":"2026-08-10T23:43:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“크— 그럼, 오늘도 힘내봅시다.”","characters":["P-d40bea4fdee0"]},{"id":"RP-0222995","time":"2026-08-10T23:44:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"길드를 빠져나온 오즈발드는, 우선 근처의 주점에 들렀습니다.\n주점은 정보의 바다, 이곳에서 사람들과 얘길 나누면 근처의 정보를 얼추 알 수 있을겁니다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0222996","time":"2026-08-10T23:45:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”과연… 이것이 골기아의 주점이군요. 역시나 사람들로 북적이는 것 같습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-0222997","time":"2026-08-10T23:45:00+09:00","room":"RP","name":"진행 / 주점 사람들","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"야! 그눠어엄은 딸꾹! 한주먹 거리야!\"\n\n\"이 사과를 니 머리위에 놔!\"\n\n\"안 씻은 드워프만큼 냄새나는 녀석아!\"\n\n주점 내부는 아비규환이었다.\n\n너무나도. 왜 이렇게 까지 북적이는걸까?","characters":[]},{"id":"RP-0222998","time":"2026-08-10T23:46:00+09:00","room":"RP","name":"진행 / 주점 사람들","profile":"피에르","identity":"reviewed","type":"dialogue","body":"하지만 그 중에서는 무언가 신비한 대화를 하는 이가 있었으니.\n\n\"아잇, 내가 그 숲에서 웬 이상한 검은놈을 봤다니까?\"\n\n\"뭔... 동물을 잘못 본거 아니야?\"\n\n\"아니래도! 진짜로 사람의 형체였었다고!\"","characters":[]},{"id":"RP-0222999","time":"2026-08-10T23:47:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…음, 소문 또한 많이 오고가는 듯 싶습니다.”","characters":["P-d40bea4fdee0"]},{"id":"RP-0223000","time":"2026-08-10T23:48:00+09:00","room":"RP","name":"진행 / 주점 사람들","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"야, 그건 별것도 아니지. 나는 지하 유적을 봤다니까? 거기에 웬 이상한 관이 있었어!\"","characters":[]},{"id":"RP-0223001","time":"2026-08-10T23:48:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“오, 과연…\n하지만 지금의 저는 아직 저러한 일거리에 눈을 들일 수준이 아니니, 곧 길드에 의뢰로 올라오겠죠.”","characters":["P-d40bea4fdee0"]},{"id":"RP-0223002","time":"2026-08-10T23:48:00+09:00","room":"RP","name":"진행 / 주점 사람들","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그 관 안에 뭐가 있었는데?\"\n\n\"당연히 쫄려서 못 열고 튀었지 임마!\"\n\n\"하하하! 쫄보같은 놈. 남자가 궁금한게 있으면 열어봐야지!\"","characters":[]},{"id":"RP-0223003","time":"2026-08-10T23:49:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드는… 쫄보다…!","characters":["P-d40bea4fdee0"]},{"id":"RP-0223004","time":"2026-08-10T23:49:00+09:00","room":"RP","name":"진행 / 주점 사람들","profile":"피에르","identity":"reviewed","type":"dialogue","body":"아무튼, 생각보다 꽤 많은 소문들이 몰려 다니고 있었지만 대다수는 의뢰로 올 것 같거나 아니면 별 볼일이 없어 보이는 의뢰들 뿐이었다.","characters":[]},{"id":"RP-0223005","time":"2026-08-10T23:51:00+09:00","room":"RP","name":"진행 / 주점 사람들","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"요즘 날씨가 더워서 거... 어디냐... 아무튼 거기는 그 길이 막 어떻게 됐다고 하지 않았어?\"\n\n\"그래? 왜 그렇대?\"\n\n\"어... 몰러! 딸꾹! 대충 저 위에 숲길이라 하던데... 으... 잠깐 장실좀.\"","characters":[]},{"id":"RP-0223006","time":"2026-08-10T23:51:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 오즈발드는 주점의 안쪽으로 들어가, 적당한 테이블을 잡아 푼돈을 얼마씩 건네며 자리에 합석해, 하나 둘 주변의 지형과 장소들을 묻고 다니는 중이다.","characters":["P-d40bea4fdee0"]},{"id":"RP-0223007","time":"2026-08-10T23:51:00+09:00","room":"RP","name":"오즈발드 윌","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아마 바쁜 듯 하니 내버려 두도록 하자잇…","characters":["P-d40bea4fdee0"]}]};
